begin;
with target as (select id from public.workspaces where name='Ball Pit Motorsports' limit 1),
track as (select t.id,t.workspace_id from public.tracks t join target w on w.id=t.workspace_id where t.name='Eagles Canyon Raceway')
insert into public.track_configurations(workspace_id,track_id,name)
select workspace_id,id,'Configuration Unknown' from track on conflict(track_id,name) do nothing;
with target as (select id from public.workspaces where name='Ball Pit Motorsports' limit 1),
owner as (select id from auth.users where lower(email)='roshan.p.vani@gmail.com' limit 1),
src as (select * from jsonb_to_recordset('[{"business_id":"EVT-GB-20260307-02","event_date":"2026-03-07","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":"Apex Driving Academy","event_name":"Apex Ranch to Canyon","event_type":"Competition / Organized Event","temperature_f":44.6,"conditions":"Rain","precipitation_in":0.21,"wind_speed_mph":4,"humidity_pct":90,"track_condition":"Wet","tire_business_id":"GB-TIRE-004","front_pad_business_id":"GB-FPAD-002","rear_pad_business_id":"GB-RPAD-002","notes":"ECR leg of Apex Ranch to Canyon\nSplit from EVT-GB-20260307-01; ECR session 3\nConfiguration was blank in the historical source."},{"business_id":"EVT-GB-20260308-01","event_date":"2026-03-08","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":null,"event_name":"Competition / Organized Event","event_type":"Competition / Organized Event","temperature_f":60.4,"conditions":"Clear","precipitation_in":0,"wind_speed_mph":1.3,"humidity_pct":52.4,"track_condition":"Dry","tire_business_id":"GB-TIRE-004","front_pad_business_id":"GB-FPAD-002","rear_pad_business_id":"GB-RPAD-002","notes":"Lap sessions: 3 | Partial | Notebook review: weekend split\nConfiguration was blank in the historical source."},{"business_id":"EVT-GB-20260322-01","event_date":"2026-03-22","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":null,"event_name":"Member / Open Track Day","event_type":"Member / Open Track Day","temperature_f":85.5,"conditions":"Clear","precipitation_in":0,"wind_speed_mph":13.3,"humidity_pct":27.2,"track_condition":"Dry","tire_business_id":"GB-TIRE-004","front_pad_business_id":"GB-FPAD-002","rear_pad_business_id":"GB-RPAD-002","notes":"Lap sessions: 2 | Lap DB | Lap DB only | Notebook p. 14\nConfiguration was blank in the historical source."},{"business_id":"EVT-GB-20260402-01","event_date":"2026-04-02","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":null,"event_name":"Member / Open Track Day","event_type":"Member / Open Track Day","temperature_f":79.2,"conditions":"Clear","precipitation_in":0,"wind_speed_mph":12.8,"humidity_pct":55.1,"track_condition":"Dry","tire_business_id":"GB-TIRE-006","front_pad_business_id":"GB-FPAD-003","rear_pad_business_id":"GB-RPAD-002","notes":"285 RE-71RS installed 4/1; new rotors and used pads\nLap sessions: 1 | Lap DB | Lap DB only | Notebook p. 14\nConfiguration was blank in the historical source."},{"business_id":"EVT-GB-20260501-01","event_date":"2026-05-01","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":null,"event_name":"Competition / Organized Event","event_type":"Competition / Organized Event","temperature_f":61,"conditions":"Partly Cloudy","precipitation_in":0,"wind_speed_mph":8.7,"humidity_pct":61.6,"track_condition":"Dry","tire_business_id":"GB-TIRE-006","front_pad_business_id":"GB-FPAD-003","rear_pad_business_id":"GB-RPAD-002","notes":"Lap sessions: 3 | Matched | Notebook confirmed\nConfiguration was blank in the historical source."},{"business_id":"EVT-GB-20260502-01","event_date":"2026-05-02","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":"SCCA","event_name":"SCCA","event_type":"Competition / Organized Event","temperature_f":69.1,"conditions":"Clear","precipitation_in":0,"wind_speed_mph":2.9,"humidity_pct":45.3,"track_condition":"Dry","tire_business_id":"GB-TIRE-006","front_pad_business_id":"GB-FPAD-003","rear_pad_business_id":"GB-RPAD-002","notes":"Lap sessions: 4 | Matched | Notebook confirmed\nConfiguration was blank in the historical source."},{"business_id":"EVT-GB-20260503-01","event_date":"2026-05-03","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":"SCCA","event_name":"SCCA","event_type":"Competition / Organized Event","temperature_f":75,"conditions":"Clear","precipitation_in":0,"wind_speed_mph":10.6,"humidity_pct":37.4,"track_condition":"Dry","tire_business_id":"GB-TIRE-006","front_pad_business_id":"GB-FPAD-003","rear_pad_business_id":"GB-RPAD-002","notes":"Lap sessions: 2 | Lap DB only | Notebook review needed\nConfiguration was blank in the historical source."},{"business_id":"EVT-GB-20260508-01","event_date":"2026-05-08","vehicle":"Golf Ball","team_name":"Ball Pit Motor","driver_name":"Roshan Vani","track_name":"Eagles Canyon Raceway","configuration_name":"Configuration Unknown","organization_name":null,"event_name":"Member / Open Track Day","event_type":"Member / Open Track Day","temperature_f":71,"conditions":"Partly Cloudy","precipitation_in":0,"wind_speed_mph":8.6,"humidity_pct":65.9,"track_condition":"Dry","tire_business_id":"GB-TIRE-006","front_pad_business_id":"GB-FPAD-003","rear_pad_business_id":"GB-RPAD-002","notes":"Lap sessions: 1 | Lap DB | Matched | Notebook p. 16\nConfiguration was blank in the historical source."}]'::jsonb) as x(business_id text,event_date date,vehicle text,team_name text,driver_name text,track_name text,configuration_name text,organization_name text,event_name text,event_type text,temperature_f numeric,conditions text,precipitation_in numeric,wind_speed_mph numeric,humidity_pct numeric,track_condition text,tire_business_id text,front_pad_business_id text,rear_pad_business_id text,notes text))
insert into public.events(workspace_id,business_id,event_date,event_name,track_name,configuration_name,organization_name,status,created_by,vehicle_id,team_name,driver_name,event_type,temperature_f,conditions,precipitation_in,wind_speed_mph,humidity_pct,track_condition,tire_set_business_id,front_pad_set_business_id,rear_pad_set_business_id,notes,track_id,configuration_id,tire_set_id,front_pad_set_id,rear_pad_set_id)
select w.id,s.business_id,s.event_date,s.event_name,s.track_name,s.configuration_name,s.organization_name,'complete',o.id,v.id,s.team_name,s.driver_name,s.event_type,s.temperature_f,s.conditions,s.precipitation_in,s.wind_speed_mph,s.humidity_pct,s.track_condition,s.tire_business_id,s.front_pad_business_id,s.rear_pad_business_id,s.notes,t.id,tc.id,ti.id,fp.id,rp.id
from src s cross join target w cross join owner o join public.vehicles v on v.workspace_id=w.id and v.name=s.vehicle join public.tracks t on t.workspace_id=w.id and t.name=s.track_name join public.track_configurations tc on tc.workspace_id=w.id and tc.track_id=t.id and tc.name=s.configuration_name left join public.tire_sets ti on ti.workspace_id=w.id and ti.business_id=s.tire_business_id left join public.pad_sets fp on fp.workspace_id=w.id and fp.business_id=s.front_pad_business_id left join public.pad_sets rp on rp.workspace_id=w.id and rp.business_id=s.rear_pad_business_id
on conflict(workspace_id,business_id) do nothing;
with target as (select id from public.workspaces where name='Ball Pit Motorsports' limit 1),
owner as (select id from auth.users where lower(email)='roshan.p.vani@gmail.com' limit 1),
src as (select * from jsonb_to_recordset('[{"event_business_id":"EVT-GB-20260307-02","session_number":3,"best_lap_ms":126610,"is_fastest":false},{"event_business_id":"EVT-GB-20260308-01","session_number":1,"best_lap_ms":128290,"is_fastest":true},{"event_business_id":"EVT-GB-20260308-01","session_number":2,"best_lap_ms":131690,"is_fastest":false},{"event_business_id":"EVT-GB-20260308-01","session_number":3,"best_lap_ms":128900,"is_fastest":false},{"event_business_id":"EVT-GB-20260322-01","session_number":1,"best_lap_ms":127890,"is_fastest":true},{"event_business_id":"EVT-GB-20260322-01","session_number":2,"best_lap_ms":128900,"is_fastest":false},{"event_business_id":"EVT-GB-20260402-01","session_number":1,"best_lap_ms":154800,"is_fastest":true},{"event_business_id":"EVT-GB-20260501-01","session_number":1,"best_lap_ms":131700,"is_fastest":false},{"event_business_id":"EVT-GB-20260501-01","session_number":2,"best_lap_ms":127310,"is_fastest":true},{"event_business_id":"EVT-GB-20260501-01","session_number":3,"best_lap_ms":128140,"is_fastest":false},{"event_business_id":"EVT-GB-20260502-01","session_number":1,"best_lap_ms":129640,"is_fastest":false},{"event_business_id":"EVT-GB-20260502-01","session_number":2,"best_lap_ms":129440,"is_fastest":true},{"event_business_id":"EVT-GB-20260502-01","session_number":3,"best_lap_ms":129440,"is_fastest":false},{"event_business_id":"EVT-GB-20260502-01","session_number":4,"best_lap_ms":129830,"is_fastest":false},{"event_business_id":"EVT-GB-20260503-01","session_number":1,"best_lap_ms":127960,"is_fastest":true},{"event_business_id":"EVT-GB-20260503-01","session_number":2,"best_lap_ms":128130,"is_fastest":false},{"event_business_id":"EVT-GB-20260508-01","session_number":1,"best_lap_ms":132800,"is_fastest":true}]'::jsonb) as x(event_business_id text,session_number integer,best_lap_ms integer,is_fastest boolean))
insert into public.sessions(workspace_id,event_id,session_number,best_lap_ms,is_fastest,created_by)
select w.id,e.id,s.session_number,s.best_lap_ms,s.is_fastest,o.id from src s cross join target w cross join owner o join public.events e on e.workspace_id=w.id and e.business_id=s.event_business_id
on conflict(event_id,session_number) do update set best_lap_ms=excluded.best_lap_ms,is_fastest=excluded.is_fastest,created_by=excluded.created_by;
commit;
